function checkStore(){return get(STORE.checks,{})}
function checkKey(){return `${$('checkAircraft')?.value||'DEMO-B737-01'}::${selectedCheckType}`}
function defaultCheckState(){const c=maintenanceCheckCatalog[selectedCheckType],tasks=c.groups.flatMap(g=>g[1]);return{aircraft:$('checkAircraft')?.value||'DEMO-B737-01',type:selectedCheckType,status:'Planning',completed:Object.fromEntries(tasks.map((_,i)=>[i,false])),updated:null}}
function currentCheckState(){const all=checkStore();return all[checkKey()]||defaultCheckState()}
function bindChecks(){
 const aircraft=$('checkAircraft');if(!aircraft)return;
 aircraft.onchange=renderChecks;$('checkPackageStatus').onchange=saveCheckProgress;
 $('saveCheckBtn').onclick=()=>saveCheckProgress(true);$('scheduleCheckBtn').onclick=scheduleSelectedCheck;$('checkWorkOrderBtn').onclick=createCheckWorkOrder;$('exportCheckBtn').onclick=exportCheckPackage;$('resetCheckBtn').onclick=resetCheckPackage;$('checkSelectAllBtn').onclick=toggleAllCheckTasks;
}
function renderChecks(){
 if(!$('checkTypeCards'))return;
 $('checkTypeCards').innerHTML=Object.entries(maintenanceCheckCatalog).map(([id,c])=>`<button class="check-type-card ${selectedCheckType===id?'selected':''}" data-check-type="${id}" style="--check-accent:${c.accent}"><span>${id}</span><div><b>${esc(c.title)}</b><small>${esc(c.short)}</small></div><i>›</i></button>`).join('');
 $$('[data-check-type]').forEach(b=>b.onclick=()=>{selectedCheckType=b.dataset.checkType;renderChecks()});
 const c=maintenanceCheckCatalog[selectedCheckType],state=currentCheckState(),tasks=c.groups.flatMap(g=>g[1]),done=tasks.filter((_,i)=>state.completed?.[i]).length,pct=Math.round(done/tasks.length*100);
 $('checkPackageStatus').value=state.status||'Planning';$('checkTypeBadge').textContent=selectedCheckType;$('checkTypeBadge').style.background=c.accent;$('checkTypeTitle').textContent=c.title;$('checkTypeDescription').textContent=c.description;$('checkProgressText').textContent=`${pct}%`;$('checkProgressBar').style.width=`${pct}%`;$('checkDoneCount').textContent=done;$('checkRemainingCount').textContent=tasks.length-done;$('checkUpdatedText').textContent=state.updated?new Date(state.updated).toLocaleDateString():'Not saved';$('checkSelectAllBtn').textContent=done===tasks.length?'Clear all':'Complete all';
 let index=0;$('checkTaskGroups').innerHTML=c.groups.map(([group,list])=>`<section class="check-task-group"><h3>${esc(group)}</h3>${list.map(task=>{const i=index++;return`<label class="check-task-row ${state.completed?.[i]?'done':''}"><input type="checkbox" data-check-task="${i}" ${state.completed?.[i]?'checked':''}><span class="check-box">✓</span><span><b>${esc(task)}</b><small>Training task — verify exact wording and acceptance criteria in approved data.</small></span></label>`}).join('')}</section>`).join('');
 $$('[data-check-task]').forEach(x=>x.onchange=()=>{const all=checkStore(),s=all[checkKey()]||defaultCheckState();s.completed??={};s.completed[x.dataset.checkTask]=x.checked;s.updated=now();s.status=$('checkPackageStatus').value;all[checkKey()]=s;set(STORE.checks,all);renderChecks()});
}
function saveCheckProgress(showToast=false){if(!$('checkAircraft'))return;const all=checkStore(),s=all[checkKey()]||defaultCheckState();s.status=$('checkPackageStatus').value;s.updated=now();all[checkKey()]=s;set(STORE.checks,all);activity('check',`${selectedCheckType}-check package saved`,`${s.aircraft} · ${s.status}`);renderChecks();if(showToast)toast('Check-package progress saved')}
function toggleAllCheckTasks(){const all=checkStore(),s=all[checkKey()]||defaultCheckState(),c=maintenanceCheckCatalog[selectedCheckType],count=c.groups.flatMap(g=>g[1]).length,isAll=Array.from({length:count},(_,i)=>!!s.completed?.[i]).every(Boolean);s.completed=Object.fromEntries(Array.from({length:count},(_,i)=>[i,!isAll]));s.updated=now();all[checkKey()]=s;set(STORE.checks,all);renderChecks()}
function scheduleSelectedCheck(){saveCheckProgress(false);const aircraft=$('checkAircraft').value,c=maintenanceCheckCatalog[selectedCheckType];openScheduleModal({title:`${c.title} training package`,aircraft,category:'A/B/C/D check package',priority:'Medium',assignee:'Scheduled Maintenance Team',notes:'Training template only. Check type does not determine operational priority. Use the current operator-approved maintenance program, due state and authorized planning judgement.'})}
function createCheckWorkOrder(){saveCheckProgress(false);const tasks=get(STORE.tasks,[]),c=maintenanceCheckCatalog[selectedCheckType],aircraft=$('checkAircraft').value,id=uid('WO');tasks.unshift({id,title:`${c.title} package planning and execution`,aircraft,priority:'Medium',status:'Open',assignee:'Scheduled Maintenance Team',created:now(),sourceCheck:selectedCheckType});set(STORE.tasks,tasks);activity('task','Check-package work order created',`${aircraft} · ${c.title}`);renderHome();toast('Check work order created')}
function exportCheckPackage(){const s=currentCheckState(),c=maintenanceCheckCatalog[selectedCheckType];saveFile(`AeroFleetX_${s.aircraft}_${selectedCheckType}_Maintenance_Program.json`,JSON.stringify({exported:now(),notice:'Training template only. Operator approved AMP and controlled maintenance data remain authoritative.',definition:c,state:s},null,2),'application/json')}
function resetCheckPackage(){if(!confirm(`Reset the ${selectedCheckType}-check training package for ${$('checkAircraft').value}?`))return;const all=checkStore();delete all[checkKey()];set(STORE.checks,all);renderChecks();toast('Training package reset')}



