function predictiveStore(){return get(STORE.predictive,{})}
function cloneTemplate(aircraft){return (predictiveTemplates[aircraft]||predictiveTemplates['DEMO-B777-01']).map(x=>({...x,history:[Math.round(x.value*0.9*10)/10,Math.round(x.value*0.93*10)/10,Math.round(x.value*0.96*10)/10,x.value]}))}
function predictiveKey(){return `${predictiveAircraft}::${predictiveProfile}`}
function currentPredictiveState(){const all=predictiveStore(),key=predictiveKey();if(!all[key]){all[key]={aircraft:predictiveAircraft,profile:predictiveProfile,components:cloneTemplate(predictiveAircraft),updated:null,cycles:0};applyPredictiveProfile(all[key]);set(STORE.predictive,all)}return all[key]}
function applyPredictiveProfile(state){state.components.forEach((c,i)=>{const t=(predictiveTemplates[state.aircraft]||predictiveTemplates['DEMO-B777-01'])[i]||c;c.value=t.value;if(state.profile==='routine')c.value=c.direction==='high'?t.value*.82:t.value*1.12;if(state.profile==='degrading')c.value=c.direction==='high'?Math.min(t.critical*.94,t.value*1.12):Math.max(t.critical*1.05,t.value*.9);c.value=Math.round(c.value*10)/10;c.history=[c.value*.92,c.value*.95,c.value*.98,c.value].map(v=>Math.round(v*10)/10)});state.updated=null;state.cycles=0}
function predictiveRisk(c){let r=0;if(c.direction==='high'){if(c.value<c.warning)r=60*(c.value/c.warning);else r=60+40*((c.value-c.warning)/(c.critical-c.warning))}else{if(c.value>c.warning)r=60*(c.warning/c.value);else r=60+40*((c.warning-c.value)/(c.warning-c.critical))}return Math.max(0,Math.min(100,Math.round(r)))}
function predictiveLevel(r){return r>=70?'High':r>=45?'Medium':'Low'}
function predictedCycles(r){if(r>=85)return 10;if(r>=70)return 25;if(r>=55)return 60;if(r>=45)return 100;return 180}
function bindPredictive(){if(!$('predictiveAircraft'))return;$('predictiveAircraft').onchange=()=>{predictiveAircraft=$('predictiveAircraft').value;renderPredictive()};$('predictiveProfile').onchange=()=>{predictiveProfile=$('predictiveProfile').value;const all=predictiveStore(),key=predictiveKey();delete all[key];set(STORE.predictive,all);renderPredictive()};$('runPredictionBtn').onclick=runPrediction;$('simulateFlightBtn').onclick=simulatePredictiveCycles;$('createPredictiveWorkOrderBtn').onclick=createPredictiveWorkOrder;$('schedulePredictiveBtn').onclick=schedulePredictiveInspection;$('exportPredictiveBtn').onclick=exportPredictiveReport;$('resetPredictiveBtn').onclick=resetPredictiveData;$('openCCheckBtn').onclick=()=>openScreen('schedule')}
function runPrediction(){const all=predictiveStore(),s=currentPredictiveState();s.updated=now();all[predictiveKey()]=s;set(STORE.predictive,all);activity('predictive','Predictive health analysis completed',`${s.aircraft} · ${s.components.filter(c=>predictiveLevel(predictiveRisk(c))==='High').length} high-risk items`);renderPredictive();toast('Health analysis completed')}
function simulatePredictiveCycles(){const all=predictiveStore(),s=currentPredictiveState();s.cycles=(s.cycles||0)+10;s.components.forEach(c=>{const factor=c.direction==='high'?1:-1;const base=Math.max(Math.abs(c.value)*.012,.25);const change=factor*(base*(.7+Math.random()*.8));c.value=Math.round((c.value+change)*10)/10;c.history=(c.history||[]).concat(c.value).slice(-8)});s.updated=now();all[predictiveKey()]=s;set(STORE.predictive,all);activity('predictive','Ten simulated cycles added',s.aircraft);renderPredictive();toast('Ten cycles simulated')}
function renderPredictive(){if(!$('predictiveComponentList'))return;predictiveAircraft=$('predictiveAircraft').value;predictiveProfile=$('predictiveProfile').value;const s=currentPredictiveState(),items=s.components.map(c=>({...c,risk:predictiveRisk(c)})).sort((a,b)=>b.risk-a.risk),high=items.filter(x=>predictiveLevel(x.risk)==='High').length,medium=items.filter(x=>predictiveLevel(x.risk)==='Medium').length,health=Math.round(items.reduce((n,x)=>n+(100-x.risk),0)/items.length),next=Math.min(...items.map(x=>predictedCycles(x.risk)));$('predictiveHealth').textContent=`${health}%`;$('predictiveHigh').textContent=high;$('predictiveMedium').textContent=medium;$('predictiveNext').textContent=`${next} cycles`;$('predictionTimestamp').textContent=s.updated?`Analysed ${new Date(s.updated).toLocaleString()}`:'Demo values ready';$('predictiveComponentList').innerHTML=items.map(componentPredictionHTML).join('');$('cCheckPriorityList').innerHTML=items.slice(0,4).map((c,i)=>`<article><b>${i+1}</b><div><strong>${esc(c.name)}</strong><span>${esc(c.cCheck)}</span></div><em class="risk-${predictiveLevel(c.risk).toLowerCase()}">${predictiveLevel(c.risk)}</em></article>`).join('');$$('[data-predictive-wo]').forEach(b=>b.onclick=()=>createPredictiveWorkOrder(b.dataset.predictiveWo));$$('[data-predictive-schedule]').forEach(b=>b.onclick=()=>schedulePredictiveInspection(b.dataset.predictiveSchedule))}
function predictionReason(c){const threshold=c.direction==='high'?`warning ${c.warning} ${c.unit}`:`warning ${c.warning} ${c.unit}`;return `${c.trend||'condition trend'}; simulated value ${c.value} ${c.unit}; ${threshold}.`}
function componentPredictionHTML(c){const level=predictiveLevel(c.risk),health=100-c.risk,points=(c.history||[c.value]).map((v,i,a)=>{const min=Math.min(...a),max=Math.max(...a),pct=max===min?50:100-(v-min)/(max-min)*100;return `${i/(Math.max(1,a.length-1))*100},${pct}`}).join(' ');return`<article class="predictive-component ${level.toLowerCase()}"><header><div><span class="eyebrow">${esc(c.system)}</span><h3>${esc(c.name)}</h3></div><span class="risk-badge risk-${level.toLowerCase()}">${level} RISK</span></header><div class="predictive-value-row"><div><strong>${esc(c.value)} ${esc(c.unit)}</strong><span>Current simulated value</span></div><div><strong>${health}%</strong><span>Health score</span></div><div><strong>${predictedCycles(c.risk)}</strong><span>Cycles to review</span></div></div><svg class="mini-trend" viewBox="0 0 100 100" preserveAspectRatio="none" aria-label="Trend"><polyline points="${points}"></polyline></svg><div class="health-track"><i style="width:${health}%"></i></div><div class="explainability-box"><b>Why this priority</b><span>${esc(predictionReason(c))}</span></div><p><b>Recommended action:</b> ${esc(c.action)}</p><div class="predictive-card-actions"><button data-predictive-wo="${esc(c.id)}">Create work order</button><button data-predictive-schedule="${esc(c.id)}">Schedule inspection</button></div></article>`}
function highestPredictive(id){const s=currentPredictiveState(),list=s.components.map(c=>({...c,risk:predictiveRisk(c)})).sort((a,b)=>b.risk-a.risk);return id?list.find(x=>x.id===id)||list[0]:list[0]}
function createPredictiveWorkOrder(id){const c=highestPredictive(id),tasks=get(STORE.tasks,[]),wo={id:uid('WO'),title:`Predictive review: ${c.name}`,aircraft:predictiveAircraft,priority:predictiveLevel(c.risk)==='High'?'High':'Medium',status:'Open',assignee:'Reliability / Maintenance Team',created:now(),sourcePredictive:c.id,notes:c.action};tasks.unshift(wo);set(STORE.tasks,tasks);activity('task','Predictive work order created',`${predictiveAircraft} · ${c.name}`);renderHome();toast('Predictive work order created')}
const aircraftDailyCycles={'DEMO-B737-01':4.5,'DEMO-B787-01':1.4,'DEMO-B777-01':1.2,'TRAINING-C130J-01':1.8};
function schedulePredictiveInspection(id){const c=highestPredictive(id),utilization=aircraftDailyCycles[predictiveAircraft]||2,days=Math.max(1,Math.round(predictedCycles(c.risk)/utilization)),due=new Date();due.setDate(due.getDate()+days);openScheduleModal({title:`Predictive inspection: ${c.name}`,aircraft:predictiveAircraft,category:'Reliability review',priority:predictiveLevel(c.risk)==='High'?'High':'Medium',assignee:'Reliability / Maintenance Team',notes:`Demo prediction: ${c.action} Estimated review within ${predictedCycles(c.risk)} cycles using a simulated utilization of ${utilization} cycles/day.`,due:due.toISOString()})}
function exportPredictiveReport(){const s=currentPredictiveState(),report={exported:now(),notice:'Educational simulated prediction only. Not approved maintenance data.',aircraft:s.aircraft,profile:s.profile,simulatedCycles:s.cycles,components:s.components.map(c=>({...c,riskScore:predictiveRisk(c),riskLevel:predictiveLevel(predictiveRisk(c)),estimatedCyclesToReview:predictedCycles(predictiveRisk(c))}))};saveFile(`AeroFleetX_${s.aircraft}_Predictive_Intelligence_Report.json`,JSON.stringify(report,null,2),'application/json');toast('Predictive report exported')}
function resetPredictiveData(){if(!confirm('Reset all simulated predictive-maintenance data?'))return;set(STORE.predictive,{});renderPredictive();toast('Predictive demo reset')}


