function clearResearchData(){if(!confirm('Erase all AeroFleetX local records, training results, work orders, schedules and predictive simulations from this device?'))return;Object.values(STORE).forEach(k=>localStorage.removeItem(k));toast('Local research data erased');setTimeout(()=>location.reload(),700)}

