/* ===== Maintenance Mission Control ===== */
function localDateKey(value){const d=value instanceof Date?value:new Date(value);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function dayStart(value=new Date()){const d=value instanceof Date?new Date(value):new Date(value);d.setHours(0,0,0,0);return d}
function scheduleState(e){if(e.status==='Completed')return'Completed';const due=dayStart(e.due),today=dayStart(),days=Math.round((due-today)/86400000);if(days<0)return'Overdue';if(days===0)return'Today';if(days<=7)return'Upcoming';return'Future'}
function formatScheduleDate(value){const d=new Date(value);return{day:d.getDate(),month:d.toLocaleDateString(undefined,{month:'short'}),full:d.toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'short',year:'numeric'}),time:d.toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'})}}
function bindSchedule(){
 $('newScheduleBtn').onclick=()=>openScheduleModal();$('saveScheduleBtn').onclick=saveScheduleEvent;$('[data-close-schedule]')&&$$('[data-close-schedule]').forEach(b=>b.onclick=()=>hideSheet('scheduleModal'));
 $$('[data-schedule-filter]').forEach(b=>b.onclick=()=>{scheduleFilter=b.dataset.scheduleFilter;$$('[data-schedule-filter]').forEach(x=>x.classList.toggle('selected',x.dataset.scheduleFilter===scheduleFilter));selectedScheduleDate='';renderScheduleList()});
 $('scheduleAircraftFilter').onchange=()=>{scheduleAircraftFilter=$('scheduleAircraftFilter').value;renderScheduleList()};
 $('prevMonthBtn').onclick=()=>{scheduleMonth=new Date(scheduleMonth.getFullYear(),scheduleMonth.getMonth()-1,1);renderScheduleCalendar()};
 $('nextMonthBtn').onclick=()=>{scheduleMonth=new Date(scheduleMonth.getFullYear(),scheduleMonth.getMonth()+1,1);renderScheduleCalendar()};
 $('exportScheduleBtn').onclick=exportScheduleICS;
}
function openScheduleModal(prefill={}){const tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);$('scheduleModalTitle').textContent=prefill.id?'Reschedule maintenance':'Schedule maintenance';$('scheduleTitle').value=prefill.title||'';$('scheduleAircraft').value=prefill.aircraft||'DEMO-B737-01';$('scheduleCategory').value=prefill.category||'Scheduled inspection';const due=prefill.due?new Date(prefill.due):tomorrow;$('scheduleDate').value=localDateKey(due);$('scheduleTime').value=`${String(due.getHours()||9).padStart(2,'0')}:${String(due.getMinutes()).padStart(2,'0')}`;$('schedulePriority').value=prefill.priority||'Medium';$('scheduleRecurrence').value=prefill.recurrence||'None';$('scheduleAssignee').value=prefill.assignee||'AeroFleetX Maintenance Team';$('scheduleNotes').value=prefill.notes||'';$('saveScheduleBtn').dataset.editId=prefill.id||'';showSheet('scheduleModal')}
function saveScheduleEvent(){const title=$('scheduleTitle').value.trim(),date=$('scheduleDate').value,time=$('scheduleTime').value||'09:00';if(!title)return toast('Enter a maintenance task');if(!date)return toast('Select a due date');const due=new Date(`${date}T${time}:00`);if(Number.isNaN(due.getTime()))return toast('Check the due date and time');const list=get(STORE.schedule,[]),editId=$('saveScheduleBtn').dataset.editId;const event={id:editId||uid('SCH'),title,aircraft:$('scheduleAircraft').value,category:$('scheduleCategory').value,due:due.toISOString(),priority:$('schedulePriority').value,status:'Scheduled',recurrence:$('scheduleRecurrence').value,assignee:$('scheduleAssignee').value.trim()||'AeroFleetX Maintenance Team',notes:$('scheduleNotes').value.trim(),created:now()};if(editId){const i=list.findIndex(x=>x.id===editId);if(i>=0)event.status=list[i].status||'Scheduled',event.created=list[i].created||now(),list[i]=event}else list.push(event);set(STORE.schedule,list);activity('schedule',editId?'Maintenance rescheduled':'Maintenance scheduled',`${event.aircraft} · ${event.title}`);hideSheet('scheduleModal');renderSchedule();renderHome();toast(editId?'Schedule updated':'Maintenance added to schedule')}
function renderSchedule(){const list=get(STORE.schedule,[]),states=list.map(scheduleState);$('schedToday').textContent=states.filter(x=>x==='Today').length;$('schedUpcoming').textContent=states.filter(x=>x==='Upcoming').length;$('schedOverdue').textContent=states.filter(x=>x==='Overdue').length;$('schedTotal').textContent=list.filter(x=>x.status!=='Completed').length;const overdue=states.filter(x=>x==='Overdue').length,alert=$('scheduleAlert');if(overdue){alert.classList.remove('hidden');alert.innerHTML=`<b>${overdue} overdue maintenance item${overdue>1?'s':''}</b> require review. Training records do not replace approved airline planning systems.`}else alert.classList.add('hidden');renderScheduleCalendar();renderScheduleList()}
function renderScheduleCalendar(){const y=scheduleMonth.getFullYear(),m=scheduleMonth.getMonth();$('calendarMonthLabel').textContent=scheduleMonth.toLocaleDateString(undefined,{month:'long',year:'numeric'});const first=new Date(y,m,1),startOffset=(first.getDay()+6)%7,last=new Date(y,m+1,0).getDate(),prevLast=new Date(y,m,0).getDate(),events=get(STORE.schedule,[]);let cells=[];for(let i=0;i<42;i++){let d,muted=false;if(i<startOffset){d=new Date(y,m-1,prevLast-startOffset+i+1);muted=true}else if(i>=startOffset+last){d=new Date(y,m+1,i-startOffset-last+1);muted=true}else d=new Date(y,m,i-startOffset+1);const key=localDateKey(d),dayEvents=events.filter(e=>localDateKey(e.due)===key&&e.status!=='Completed'),over=dayEvents.some(e=>scheduleState(e)==='Overdue');cells.push(`<button class="calendar-day ${muted?'muted':''} ${key===localDateKey(new Date())?'today':''} ${key===selectedScheduleDate?'selected':''} ${dayEvents.length?'has-events':''} ${over?'has-overdue':''}" data-calendar-date="${key}">${d.getDate()}</button>`)}$('scheduleCalendar').innerHTML=cells.join('');$$('[data-calendar-date]').forEach(b=>b.onclick=()=>{selectedScheduleDate=selectedScheduleDate===b.dataset.calendarDate?'':b.dataset.calendarDate;renderScheduleCalendar();renderScheduleList()})}
function renderScheduleList(){let list=get(STORE.schedule,[]);if(scheduleAircraftFilter!=='All')list=list.filter(e=>e.aircraft===scheduleAircraftFilter);if(selectedScheduleDate)list=list.filter(e=>localDateKey(e.due)===selectedScheduleDate);else if(scheduleFilter!=='All')list=list.filter(e=>scheduleState(e)===scheduleFilter||(scheduleFilter==='Upcoming'&&scheduleState(e)==='Future'&&new Date(e.due)-new Date()<=30*86400000));list.sort((a,b)=>new Date(a.due)-new Date(b.due));$('scheduleListTitle').textContent=selectedScheduleDate?`Work on ${new Date(selectedScheduleDate+'T12:00:00').toLocaleDateString(undefined,{day:'numeric',month:'long'})}`:{Today:'Due today',Upcoming:'Upcoming work',Overdue:'Overdue work',Completed:'Completed work',All:'All maintenance'}[scheduleFilter];$('scheduleList').innerHTML=list.length?list.map(scheduleEventHTML).join(''):`<div class="schedule-empty"><span>◫</span><b>No maintenance items found</b><p>Use + to schedule a new task or select another filter.</p></div>`;$$('[data-schedule-action]').forEach(b=>b.onclick=()=>scheduleAction(b.dataset.id,b.dataset.scheduleAction))}
function scheduleEventHTML(e){const f=formatScheduleDate(e.due),state=scheduleState(e),priority=e.priority.toLowerCase();return`<article class="schedule-event ${priority} ${state.toLowerCase()}"><header><div><span class="eyebrow">${esc(e.aircraft)} · ${esc(e.category)}</span><h3>${esc(e.title)}</h3><div class="event-meta">Assigned to ${esc(e.assignee)}${e.notes?`<br>${esc(e.notes)}`:''}</div></div><div class="event-date-box"><strong>${esc(f.month)} ${f.day}</strong><span>${esc(f.time)}</span></div></header><div class="event-tags"><span class="event-tag priority-${priority}">${esc(e.priority)}</span><span class="event-tag">${esc(state)}</span>${e.recurrence!=='None'?`<span class="event-tag">↻ ${esc(e.recurrence)}</span>`:''}</div><div class="schedule-actions">${e.status!=='Completed'?`<button class="primary-action" data-schedule-action="complete" data-id="${e.id}">Complete</button><button data-schedule-action="reschedule" data-id="${e.id}">Reschedule</button><button data-schedule-action="workorder" data-id="${e.id}">Create work order</button>`:''}<button data-schedule-action="delete" data-id="${e.id}">Delete</button></div></article>`}
function scheduleAction(id,action){const list=get(STORE.schedule,[]),i=list.findIndex(x=>x.id===id);if(i<0)return;const e=list[i];if(action==='complete'){e.status='Completed';activity('schedule','Scheduled maintenance completed',`${e.aircraft} · ${e.title}`);if(e.recurrence&&e.recurrence!=='None'){const next={...e,id:uid('SCH'),status:'Scheduled',due:nextRecurringDate(e.due,e.recurrence),created:now()};list.push(next)}}else if(action==='reschedule')return openScheduleModal(e);else if(action==='workorder'){const tasks=get(STORE.tasks,[]);tasks.unshift({id:uid('WO'),title:e.title,aircraft:e.aircraft,priority:e.priority,status:'Open',assignee:e.assignee,created:now(),sourceSchedule:e.id});set(STORE.tasks,tasks);activity('task','Work order created from schedule',`${e.aircraft} · ${e.title}`);toast('Work order created')}else if(action==='delete'){if(!confirm('Delete this scheduled maintenance item?'))return;list.splice(i,1)}set(STORE.schedule,list);renderSchedule();renderHome();if(action==='complete')toast('Maintenance marked complete')}
function nextRecurringDate(value,rec){const d=new Date(value);if(rec==='Daily')d.setDate(d.getDate()+1);else if(rec==='Weekly')d.setDate(d.getDate()+7);else if(rec==='Monthly')d.setMonth(d.getMonth()+1);else if(rec==='Every 3 months')d.setMonth(d.getMonth()+3);else if(rec==='Every 6 months')d.setMonth(d.getMonth()+6);else if(rec==='Yearly')d.setFullYear(d.getFullYear()+1);return d.toISOString()}
function renderHomeSchedule(){const el=$('homeScheduleList');if(!el)return;const list=get(STORE.schedule,[]).filter(e=>e.status!=='Completed').sort((a,b)=>new Date(a.due)-new Date(b.due)).slice(0,3);el.innerHTML=list.length?list.map(e=>{const f=formatScheduleDate(e.due),s=scheduleState(e);return`<button class="home-schedule-item" data-home-schedule="${e.id}"><span class="home-schedule-date"><b>${f.day}</b><small>${f.month}</small></span><div><strong>${esc(e.title)}</strong><span>${esc(e.aircraft)} · ${esc(e.assignee)}</span></div><em class="due-badge ${s.toLowerCase()}">${esc(s)}</em></button>`}).join(''):`<div class="schedule-empty"><b>No scheduled maintenance</b><p>Add an item in the Mission Control.</p></div>`;$$('[data-home-schedule]').forEach(b=>b.onclick=()=>openScreen('schedule'))}
function exportScheduleICS(){const events=get(STORE.schedule,[]).filter(e=>e.status!=='Completed');const dt=v=>new Date(v).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const clean=s=>String(s||'').replace(/([,;\\])/g,'\\$1').replace(/\n/g,'\\n');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//TROJANS//AeroFleetX Mission Control 1.0//EN','CALSCALE:GREGORIAN'];events.forEach(e=>lines.push('BEGIN:VEVENT',`UID:${e.id}@trojans-aerofleetx`,`DTSTAMP:${dt(new Date())}`,`DTSTART:${dt(e.due)}`,`SUMMARY:${clean(e.title)} - ${clean(e.aircraft)}`,`DESCRIPTION:${clean(`${e.category}; Priority ${e.priority}; Assigned ${e.assignee}; ${e.notes||''}`)}`,'END:VEVENT'));lines.push('END:VCALENDAR');saveFile(`AeroFleetX_Maintenance_Mission_Control_${localDateKey(new Date())}.ics`,lines.join('\r\n'),'text/calendar')}
